function simpleJsxTransform(src: string): string {
  // Strip TypeScript types and simple JSX annotations if needed
  return src
    .replace(/: [A-Z][a-zA-Z0-9<>\[\]| &]*/g, '')
    .replace(/<([A-Za-z0-9_]+)([^>]*)>(.*?)<\/\1>/gs, (_, tag, attrs, children) => {
      return `React.createElement("${tag}", null, "${children.trim()}")`;
    });
}

function assert(value: any, message?: string | Error): asserts value {
  if (!value) {
    if (message instanceof Error) throw message;
    throw new Error(message || 'Assertion failed');
  }
}

function deepStrictEqual(actual: any, expected: any, message?: string | Error) {
    if (JSON.stringify(actual) !== JSON.stringify(expected)) {
      if (message instanceof Error) throw message;
      throw new Error(message || `Expected values to be deeply equal`);
    }
  }

function notStrictEqual(actual: any, expected: any, message?: string | Error) {
    if (Object.is(actual, expected)) {
      if (message instanceof Error) throw message;
      throw new Error(message || `Expected values not to be strictly equal: ${actual}`);
    }
  }

function ok(value: any, message?: string | Error): asserts value {
    assert(value, message);
  }

function strictEqual(actual: any, expected: any, message?: string | Error) {
    if (!Object.is(actual, expected)) {
      if (message instanceof Error) throw message;
      throw new Error(message || `Expected values to be strictly equal: ${actual} !== ${expected}`);
    }
  }

function throws(fn: () => any, message?: string | Error) {
    let threw = false;
    try {
      fn();
    } catch (_) {
      threw = true;
    }
    if (!threw) {
      if (message instanceof Error) throw message;
      throw new Error(message || 'Missing expected exception');
    }
  }

