constructor(private bridge: WorkerBridge, adapter?: PersistenceAdapter | null) {
    this.adapter = adapter || null;
  }

async mkdir(path: string, options?: { recursive?: boolean }): Promise<void> {
    await this.bridge.request({
      type: 'fs:mkdir',
      id: nextId(),
      path,
      recursive: options?.recursive ?? true,
    });
  }

off(event: 'change', listener: FileChangeListener): void {
    if (event !== 'change') return;
    this.bridge.offFsChange(listener);
  }

on(event: 'change', listener: FileChangeListener): () => void {
    if (event !== 'change') {
      throw new Error(`Unsupported fs event: ${event}`);
    }
    return this.bridge.onFsChange(listener);
  }

async readFile(path: string, encoding?: 'utf-8'): Promise<Uint8Array | string> {
    const res = await this.bridge.request<Uint8Array>({
      type: 'fs:read',
      id: nextId(),
      path,
    });
    if (encoding === 'utf-8') {
      return new TextDecoder().decode(res);
    }
    return res;
  }

async readdir(path: string): Promise<string[]> {
    return await this.bridge.request<string[]>({
      type: 'fs:readdir',
      id: nextId(),
      path,
    });
  }

async rm(path: string, options?: { recursive?: boolean }): Promise<void> {
    await this.bridge.request({
      type: 'fs:rm',
      id: nextId(),
      path,
      recursive: options?.recursive ?? false,
