    const encoded = Buffer.from(string, encoding);
    const writeLen = Math.min(encoded.length, length !== undefined ? length : this.length - offset);
    for (let i = 0; i < writeLen; i++) {
      this[offset + i] = encoded[i];
    }
    return writeLen;
  }

